import { sqliteTable, text, integer, real } from "drizzle-orm/sqlite-core";

/**
 * Trading signals generated by the probability estimator.
 * Each signal represents the bot's assessment of a market.
 */
export const signals = sqliteTable("signals", {
  /** UUID */
  id: text("id").primaryKey(),
  /** Market ticker */
  ticker: text("ticker").notNull(),
  /** Series ticker for grouping */
  seriesTicker: text("series_ticker").notNull(),
  /** Our estimated probability (0-1) */
  estimatedProb: real("estimated_prob").notNull(),
  /** Confidence in our estimate (0-1) */
  confidence: real("confidence").notNull(),
  /** Market YES price at signal time (0-1) */
  marketPrice: real("market_price").notNull(),
  /** Edge = estimatedProb - marketPrice */
  edge: real("edge").notNull(),
  /** Edge threshold used for this signal */
  edgeThreshold: real("edge_threshold").notNull(),
  /** "buy_yes", "buy_no", "skip" */
  recommendation: text("recommendation").notNull(),
  /** "yes" or "no" — which side has edge */
  side: text("side"),
  /** Kelly-optimal fraction */
  kellyFraction: real("kelly_fraction"),
  /** Number of ensemble members used */
  ensembleSize: integer("ensemble_size"),
  /** JSON blob of reasoning details for the `explain` command */
  reasoning: text("reasoning"),
  /** Was this signal acted on? */
  acted: integer("acted", { mode: "boolean" }).notNull().default(false),
  /** Order ID if acted on */
  orderId: text("order_id"),
  /** Skip reason if not acted on */
  skipReason: text("skip_reason"),
  createdAt: text("created_at").notNull(),
  /** True when this signal was generated while bot was in dry-run/paper mode. */
  dryRun: integer("dry_run", { mode: "boolean" }).notNull().default(false),
});

export type Signal = typeof signals.$inferSelect;
export type NewSignal = typeof signals.$inferInsert;
